import { waitFor } from '@testing-library/react';

import type { AudioTrackSummary } from '../../api/contentSchemas';
import { playerStore } from '../../player';
import { launchPlaylistPlayback } from './launchPlayback';

const tracks: AudioTrackSummary[] = [
  {
    contentType: 'audioTrack',
    id: 'track-1',
    title: 'Night',
    artworkUrl: '',
    artistNames: ['Finite Ensemble'],
    albumId: null,
    albumTitle: null,
    duration: '3:00',
    mediaType: 'audio',
    streamUrl: '/content/mediaTrack/stream/track-1'
  },
  {
    contentType: 'audioTrack',
    id: 'track-2',
    title: 'Dawn',
    artworkUrl: '',
    artistNames: ['Finite Ensemble'],
    albumId: null,
    albumTitle: null,
    duration: '4:00',
    mediaType: 'audio',
    streamUrl: '/content/mediaTrack/stream/track-2'
  }
];

test('Playlist launch snapshots the ready queue and records only the explicit start track', async () => {
  const idleSnapshot = playerStore.getSnapshot();
  const launch = vi.spyOn(playerStore, 'launchQueue').mockResolvedValue();
  vi.spyOn(playerStore, 'getSnapshot').mockReturnValue({
    ...idleSnapshot,
    status: 'playing',
    currentItem: {
      id: 'track-2',
      title: 'Dawn',
      artworkUrl: '',
      artistNames: ['Finite Ensemble'],
      mediaType: 'audio',
      streamUrl: '/content/mediaTrack/stream/track-2'
    }
  });
  const fetchMock = vi.fn(async (_input: RequestInfo | URL, init?: RequestInit) => {
    const target = JSON.parse(String(init?.body));
    return new Response(JSON.stringify({ ...target, recorded: true }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' }
    });
  });
  vi.stubGlobal('fetch', fetchMock);

  await launchPlaylistPlayback(tracks, 'viewer-1', 'track-2');

  expect(launch).toHaveBeenCalledWith([
    expect.objectContaining({ id: 'track-1' }),
    expect.objectContaining({ id: 'track-2' })
  ], 1);
  await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(1));
  expect(fetchMock).toHaveBeenCalledWith(
    '/content/me/recently-played',
    expect.objectContaining({
      body: JSON.stringify({ contentType: 'audioTrack', contentId: 'track-2' }),
      method: 'POST'
    })
  );
  expect(new Headers(fetchMock.mock.calls[0][1]?.headers).get('X-Finitude-Account-Viewer')).toBe('viewer-1');
});

test('a superseded Playlist launch cannot borrow the newer queue state for activity', async () => {
  const idleSnapshot = playerStore.getSnapshot();
  let finishFirstLaunch: (() => void) | undefined;
  vi.spyOn(playerStore, 'launchQueue')
    .mockImplementationOnce(() => new Promise<void>((resolve) => {
      finishFirstLaunch = resolve;
    }))
    .mockResolvedValueOnce();
  vi.spyOn(playerStore, 'getSnapshot').mockReturnValue({
    ...idleSnapshot,
    status: 'playing',
    currentItem: {
      id: 'track-2',
      title: 'Dawn',
      artworkUrl: '',
      artistNames: ['Finite Ensemble'],
      mediaType: 'audio',
      streamUrl: '/content/mediaTrack/stream/track-2'
    }
  });
  const fetchMock = vi.fn(async (_input: RequestInfo | URL, init?: RequestInit) => {
    const target = JSON.parse(String(init?.body));
    return new Response(JSON.stringify({ ...target, recorded: true }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' }
    });
  });
  vi.stubGlobal('fetch', fetchMock);

  const first = launchPlaylistPlayback([tracks[0]], 'viewer-1');
  await launchPlaylistPlayback([tracks[1]], 'viewer-1');
  finishFirstLaunch?.();
  await first;

  await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(1));
  expect(fetchMock).toHaveBeenCalledWith(
    '/content/me/recently-played',
    expect.objectContaining({
      body: JSON.stringify({ contentType: 'audioTrack', contentId: 'track-2' })
    })
  );
});

import { advanceAccountEpoch } from '../../api/accountEpoch';
import { subscribeToAccountSessionChanges } from '../../api/accountSessionEvents';
import { launchAlbumPlayback, launchStandalonePlayback } from './launchPlayback';

test.each(['standalone', 'album', 'playlist'] as const)('a delayed %s start keeps public playback but cannot write for an exited account', async kind => {
  let complete!: () => void;
  const method = kind === 'standalone' ? 'launchStandalone' : kind === 'album' ? 'launchAlbumQueue' : 'launchQueue';
  vi.spyOn(playerStore, method).mockImplementation(() => new Promise<void>(resolve => { complete = resolve; }));
  const playing = { ...playerStore.getSnapshot(), status: 'playing' as const, currentItem: { ...tracks[0], id: tracks[0].id } };
  vi.spyOn(playerStore, 'getSnapshot').mockReturnValue(playing);
  const fetchMock = vi.fn(async () => new Response(JSON.stringify({ code: 'account_viewer_mismatch' }), { status: 409 }));
  vi.stubGlobal('fetch', fetchMock);
  const changes = vi.fn();
  const unsubscribe = subscribeToAccountSessionChanges(changes);
  const launch = kind === 'standalone' ? launchStandalonePlayback(tracks[0], 'old-viewer')
    : kind === 'album' ? launchAlbumPlayback('album', tracks, 'old-viewer') : launchPlaylistPlayback(tracks, 'old-viewer');
  advanceAccountEpoch();
  complete(); await launch;
  // Flush the lazy history module too: no response may initiate another account transition.
  await vi.dynamicImportSettled();
  expect(fetchMock).not.toHaveBeenCalled();
  expect(changes).not.toHaveBeenCalled();
  expect(playerStore.getSnapshot()).toBe(playing);
  unsubscribe();
});

import { RoomPlaybackActiveError } from '../../player';
import {
  DeferredAlbumLoadTimeoutError,
  deferredAlbumLoadLimitMs,
  launchAlbumPlaybackAfterLoad
} from './launchPlayback';

/** Resolves an Album load on demand so a test can act while the card's load is in flight. */
const deferredTracks = () => {
  let resolve!: (value: AudioTrackSummary[]) => void;
  const promise = new Promise<AudioTrackSummary[]>((settle) => { resolve = settle; });
  return { load: () => promise, resolve };
};

const recordingFetch = () => vi.fn(async (_input: RequestInfo | URL, init?: RequestInit) => {
  const target = JSON.parse(String(init?.body));
  return new Response(JSON.stringify({ ...target, recorded: true }), {
    status: 200,
    headers: { 'Content-Type': 'application/json' }
  });
});

test('an Album card launch loads the canonical queue and records only the Album', async () => {
  const launch = vi.spyOn(playerStore, 'launchAlbumQueue').mockResolvedValue();
  vi.spyOn(playerStore, 'getSnapshot').mockReturnValue({
    ...playerStore.getSnapshot(),
    status: 'playing',
    currentItem: { ...tracks[0], id: tracks[0].id }
  });
  const fetchMock = recordingFetch();
  vi.stubGlobal('fetch', fetchMock);

  await expect(launchAlbumPlaybackAfterLoad('album-1', async () => tracks, 'viewer-1')).resolves.toBe('started');

  expect(launch).toHaveBeenCalledWith([
    expect.objectContaining({ id: 'track-1' }),
    expect.objectContaining({ id: 'track-2' })
  ], 0);
  await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(1));
  expect(fetchMock).toHaveBeenCalledWith(
    '/content/me/recently-played',
    expect.objectContaining({ body: JSON.stringify({ contentType: 'album', contentId: 'album-1' }) })
  );
});

test('a newer launch during an Album card load abandons the Album', async () => {
  const albumLaunch = vi.spyOn(playerStore, 'launchAlbumQueue').mockResolvedValue();
  const standaloneLaunch = vi.spyOn(playerStore, 'launchStandalone').mockResolvedValue();
  vi.stubGlobal('fetch', recordingFetch());
  const load = deferredTracks();

  const cardLaunch = launchAlbumPlaybackAfterLoad('album-1', load.load);
  await launchStandalonePlayback(tracks[1]);
  load.resolve(tracks);

  await expect(cardLaunch).resolves.toBe('superseded');
  expect(standaloneLaunch).toHaveBeenCalledTimes(1);
  expect(albumLaunch).not.toHaveBeenCalled();
});

test('an account change during an Album card load abandons the launch and its activity', async () => {
  const albumLaunch = vi.spyOn(playerStore, 'launchAlbumQueue').mockResolvedValue();
  const fetchMock = recordingFetch();
  vi.stubGlobal('fetch', fetchMock);
  const load = deferredTracks();

  const cardLaunch = launchAlbumPlaybackAfterLoad('album-1', load.load, 'old-viewer');
  advanceAccountEpoch();
  load.resolve(tracks);

  await expect(cardLaunch).resolves.toBe('superseded');
  await vi.dynamicImportSettled();
  expect(albumLaunch).not.toHaveBeenCalled();
  expect(fetchMock).not.toHaveBeenCalled();
});

test('a signed-out Album card load is abandoned when an account signs in during the load', async () => {
  const albumLaunch = vi.spyOn(playerStore, 'launchAlbumQueue').mockResolvedValue();
  const load = deferredTracks();

  const cardLaunch = launchAlbumPlaybackAfterLoad('album-1', load.load);
  advanceAccountEpoch();
  load.resolve(tracks);

  await expect(cardLaunch).resolves.toBe('superseded');
  expect(albumLaunch).not.toHaveBeenCalled();
});

test('an Album card launch starts nothing for an Album without playable MediaTracks', async () => {
  const albumLaunch = vi.spyOn(playerStore, 'launchAlbumQueue').mockResolvedValue();

  await expect(launchAlbumPlaybackAfterLoad('album-1', async () => [], 'viewer-1')).resolves.toBe('empty');
  expect(albumLaunch).not.toHaveBeenCalled();
});

test('a failed Album card load rejects without touching the player', async () => {
  const albumLaunch = vi.spyOn(playerStore, 'launchAlbumQueue').mockResolvedValue();
  const before = playerStore.getSnapshot();

  await expect(launchAlbumPlaybackAfterLoad('album-1', async () => {
    throw new Error('album unavailable');
  }, 'viewer-1')).rejects.toThrow('album unavailable');
  expect(albumLaunch).not.toHaveBeenCalled();
  expect(playerStore.getSnapshot()).toBe(before);
});

test('an abandoned Album card load keeps the Recently Played entry of a launch that is still starting', async () => {
  let finishStandalone!: () => void;
  vi.spyOn(playerStore, 'launchStandalone').mockImplementation(() => new Promise<void>((resolve) => {
    finishStandalone = resolve;
  }));
  vi.spyOn(playerStore, 'getSnapshot').mockReturnValue({
    ...playerStore.getSnapshot(),
    status: 'playing',
    currentItem: { ...tracks[1], id: tracks[1].id }
  });
  const fetchMock = recordingFetch();
  vi.stubGlobal('fetch', fetchMock);

  const standalone = launchStandalonePlayback(tracks[1], 'viewer-1');
  await expect(launchAlbumPlaybackAfterLoad('album-1', async () => [], 'viewer-1')).resolves.toBe('empty');
  await expect(launchAlbumPlaybackAfterLoad('album-1', async () => {
    throw new Error('album unavailable');
  }, 'viewer-1')).rejects.toThrow('album unavailable');
  finishStandalone();
  await standalone;

  await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(1));
  expect(fetchMock).toHaveBeenCalledWith(
    '/content/me/recently-played',
    expect.objectContaining({ body: JSON.stringify({ contentType: 'audioTrack', contentId: 'track-2' }) })
  );
});

test('the later of two Album card gestures wins even when the earlier load finishes last', async () => {
  const albumLaunch = vi.spyOn(playerStore, 'launchAlbumQueue').mockResolvedValue();
  const first = deferredTracks();
  const second = deferredTracks();

  const firstLaunch = launchAlbumPlaybackAfterLoad('album-first', first.load);
  const secondLaunch = launchAlbumPlaybackAfterLoad('album-second', second.load);
  second.resolve([tracks[1]]);
  await expect(secondLaunch).resolves.toBe('started');
  first.resolve([tracks[0]]);
  await expect(firstLaunch).resolves.toBe('superseded');

  expect(albumLaunch).toHaveBeenCalledTimes(1);
  expect(albumLaunch).toHaveBeenCalledWith([expect.objectContaining({ id: 'track-2' })], 0);
});

test('a load that fails after the listener chose something else is not reported as a failure', async () => {
  vi.spyOn(playerStore, 'launchStandalone').mockResolvedValue();
  let reject!: (error: Error) => void;
  const pending = new Promise<AudioTrackSummary[]>((_resolve, fail) => { reject = fail; });

  const cardLaunch = launchAlbumPlaybackAfterLoad('album-1', () => pending);
  await launchStandalonePlayback(tracks[1]);
  reject(new Error('album unavailable'));

  await expect(cardLaunch).resolves.toBe('superseded');
});

test('an Album card load that outlives the user-intent window fails and never starts later', async () => {
  vi.useFakeTimers();
  try {
    const albumLaunch = vi.spyOn(playerStore, 'launchAlbumQueue').mockResolvedValue();
    const load = deferredTracks();

    const cardLaunch = launchAlbumPlaybackAfterLoad('album-1', load.load);
    const outcome = expect(cardLaunch).rejects.toBeInstanceOf(DeferredAlbumLoadTimeoutError);
    await vi.advanceTimersByTimeAsync(deferredAlbumLoadLimitMs);
    await outcome;
    load.resolve(tracks);
    await vi.advanceTimersByTimeAsync(0);

    expect(albumLaunch).not.toHaveBeenCalled();
  } finally {
    vi.useRealTimers();
  }
});

test('an Album card launch refused by room playback reports the room instead of a load failure', async () => {
  vi.spyOn(playerStore, 'launchAlbumQueue').mockRejectedValue(new RoomPlaybackActiveError());

  await expect(launchAlbumPlaybackAfterLoad('album-1', async () => tracks, 'viewer-1')).resolves.toBe('roomActive');
});
